detaileddescription.para:
You must call restore() on the checkpoint to free it. Losing the checkpoint pointer without calling restore() causes a memory leak.

allocations autoarena=cslt::move(cslt::ArenaAllocator::Heap(8192).value());

//Makesomepermanentallocations
void*permanent1=arena->alloc(256).value();
void*permanent2=arena->alloc(512).value();

//Savecheckpointbeforetemporarywork
void*checkpoint=arena->save();

//Maketemporaryallocations
void*temp1=arena->alloc(1024).value();
void*temp2=arena->alloc(2048).value();

//Rollback-freestemp1andtemp2
arena->restore(checkpoint);

//permanent1andpermanent2stillvalid
//temp1andtemp2nowINVALID
